export const statuses=['Unknown','Reading','Completed','OnHold','Dropped','PlanToRead','Rereading'];
export const labels={Unknown:'Keep original / unknown',Reading:'Reading',Completed:'Completed',OnHold:'On hold',Dropped:'Dropped',PlanToRead:'Plan to read',Rereading:'Re-reading'};
