export const emptyEntry=()=>({key:crypto.randomUUID(),title:'',matchState:'Pending',matchQueries:[],matchCandidates:[],matchError:'',anilistId:null,malId:null,contentRating:'Unknown',contentRatingSource:'',alternativeTitles:[],author:'',artist:'',source:'',url:'',categories:[],dateAdded:'',lastUpdated:'',originalChapters:0,originalScore:0,originalStatus:'Unknown',totalChapters:null,totalVolumes:null,trackers:[],included:true,status:'Unknown',score:0,scoreScale:10,chapters:0,volumes:0,startDate:'',finishDate:'',mediaId:null,matchedTitle:'',confidence:'Unmatched',matchConfirmed:false,duplicateAcknowledged:false,possibleDuplicate:false,warnings:[]});
export const contentRatings=['Unknown','SFW','NSFW'];
