export function trackerStatus(service,status){return ({1:'Reading',2:'Completed',3:'OnHold',4:'Dropped',...(service===1?{6:'PlanToRead',7:'Rereading'}:service===2?{5:'PlanToRead',6:'Rereading'}:{})})[status]??'Unknown';}
export function convertScore(value,scale,destination){if(!Number.isFinite(value)||![5,10,100].includes(scale)||value<0||value>scale)throw Error(`Score must be between 0 (no score) and ${scale}.`);return Math.round(value/scale*(destination==='AniList'?100:10));}
export function initialize(entry,settings){const e=structuredClone(entry),service=settings.destination==='AniList'?2:1,t=e.trackers.find(t=>t.service===service),original=t??e.trackers.find(t=>[1,2].includes(t.service));e.anilistId=e.trackers.find(t=>t.service===2)?.mediaId||null;e.malId=e.trackers.find(t=>t.service===1)?.mediaId||null;e.originalStatus=original?trackerStatus(original.service,original.status):'Unknown';e.originalScore=original?.score??0;e.status=settings.defaultStatus==='Unknown'?(e.originalStatus==='Unknown'?settings.missingStatus??'Unknown':e.originalStatus):settings.defaultStatus;e.score=settings.defaultScore;e.scoreScale=settings.scoreScale;const progress=Math.max(e.originalChapters,original?.chapters??0);e.chapters=Number.isFinite(progress)?Math.floor(progress):0;e.volumes=0;e.startDate=original?.startDate??'';e.finishDate=original?.finishDate??'';e.totalChapters=original?.totalChapters>0?original.totalChapters:null;e.mediaId=t?.mediaId>0?t.mediaId:null;e.matchedTitle=t?.mediaId>0?t.title||e.title:'';e.matchConfirmed=!!e.mediaId;e.confidence=e.matchConfirmed?'High · tracker ID':'Unmatched';e.matchState=e.matchConfirmed?'Matched':'Pending';e.duplicateAcknowledged=false;return e;}
