export const statusCode=(destination,status)=>destination==='AniList'?({Reading:'CURRENT',Completed:'COMPLETED',OnHold:'PAUSED',Dropped:'DROPPED',PlanToRead:'PLANNING',Rereading:'REPEATING'})[status]:({Reading:'reading',Completed:'completed',OnHold:'on_hold',Dropped:'dropped',PlanToRead:'plan_to_read',Rereading:'completed'})[status];
export function csvCell(value){let text=String(value??'');if(/^[\s]*[=+\-@]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}
export function reviewCsv(entries,settings){const headings=['Title','Alternative titles','Author','Artist','Source','Source URL','Categories','Included','Destination ID','Destination title','Status','Score','Score scale','Chapters','Original chapter progress','Volumes','Total chapters','Total volumes','Start date','Finish date','Date added','Last updated','Match confidence','Validation','Warnings','Content rating','Content rating source'];return headings.join(',')+'\r\n'+entries.map(e=>[e.title,e.alternativeTitles.join(' | '),e.author,e.artist,e.source,e.url,e.categories.join(' | '),e.included,e.mediaId,e.matchedTitle,e.status,e.score,e.scoreScale,e.chapters,e.originalChapters,e.volumes,e.totalChapters,e.totalVolumes,e.startDate,e.finishDate,e.dateAdded,e.lastUpdated,e.confidence,validate(e,settings).join('; ')||'Ready',e.warnings.join('; '),e.contentRating,e.contentRatingSource].map(csvCell).join(',')).join('\r\n');}
export function saveProject(entries,settings,warnings=[]){return JSON.stringify({type:'mapo-web-project',version:2,settings:Object.fromEntries(Object.keys(defaultSettings()).map(k=>[k,settings[k]])),entries:entries.map(cleanEntry),warnings},null,2);}
function cleanEntry(raw){const e=emptyEntry();for(const key of Object.keys(e)){if(raw[key]!==undefined)e[key]=structuredClone(raw[key]);}for(const k of ['title','author','artist','source','url','dateAdded','lastUpdated','startDate','finishDate','matchedTitle','confidence'])if(typeof e[k]!=='string')throw Error('The project contains an invalid text field.');for(const k of ['alternativeTitles','categories','warnings']){if(typeof e[k]==='string')e[k]=e[k].split(k==='alternativeTitles'?'|':',').map(v=>v.trim()).filter(Boolean);if(!Array.isArray(e[k])||!e[k].every(v=>typeof v==='string'))throw Error('The project contains invalid metadata.');}if(!['Pending','Matched','Uncertain','NotFound','Error'].includes(e.matchState)||!Array.isArray(e.matchQueries)||!e.matchQueries.every(q=>typeof q==='string')||!Array.isArray(e.matchCandidates)||e.matchCandidates.some(c=>!c||!Number.isInteger(c.id)||typeof c.title!=='string'))throw Error('Invalid matching progress.');if(!contentRatings.includes(e.contentRating)||!['','Manual','Backup tag','Matched platform'].includes(e.contentRatingSource))throw Error('Invalid content rating.');if(!Array.isArray(e.trackers))throw Error('Invalid project trackers.');for(const k of ['chapters','volumes','score','scoreScale','originalChapters','originalScore'])if(!Number.isFinite(e[k]))throw Error('The project contains invalid numbers.');if(!statuses.includes(e.status)||!statuses.includes(e.originalStatus))throw Error('The project contains an invalid reading status.');for(const k of ['included','matchConfirmed','duplicateAcknowledged'])if(typeof e[k]!=='boolean')throw Error('The project contains invalid inclusion or matching flags.');return e;}
export function loadProject(text){if(text.length>MAX_BYTES)throw Error('Project exceeds the size limit.');let p;try{p=JSON.parse(text);}catch{throw Error('The project is not valid JSON.');}if(p.Version===1){const camel=o=>Object.fromEntries(Object.entries(o).map(([k,v])=>[k[0].toLowerCase()+k.slice(1),v]));p={version:2,settings:camel(p.Settings),entries:p.Entries.map(raw=>{const e=camel(raw);e.status=statuses[e.status];e.originalStatus=statuses[e.originalStatus];e.scoreScale=p.Settings.ScoreScale;e.trackers=e.trackers.map(camel);return e;}),warnings:p.Warnings};p.settings.destination=p.settings.destination===0?'AniList':'MyAnimeList';p.settings.defaultStatus=statuses[p.settings.defaultStatus];}if(p.version!==2||!Array.isArray(p.entries)||!p.settings)throw Error('This is not a supported Hikkoshi conversion project.');const s={...defaultSettings()};for(const k of Object.keys(s))if(p.settings[k]!==undefined)s[k]=p.settings[k];if(!['AniList','MyAnimeList'].includes(s.destination)||!statuses.includes(s.defaultStatus)||!['review','skip','report'].includes(s.policy))throw Error('Invalid project settings.');convertScore(s.defaultScore,s.scoreScale,s.destination);if(!statuses.includes(s.missingStatus)||!['preserve','replace'].includes(s.existingPolicy))throw Error('Invalid import defaults.');const entries=p.entries.map(cleanEntry);if(new Set(entries.map(e=>e.key)).size!==entries.length)throw Error('Project entry identifiers must be unique.');return {settings:s,entries,warnings:Array.isArray(p.warnings)?p.warnings.filter(v=>typeof v==='string'):[]};}
export function filterEntries(entries,query='',filter='All',settings=defaultSettings(),contentFilter='All'){const q=normalize(query);return entries.filter(e=>(contentFilter==='All'||(contentFilter==='HideNSFW'?e.contentRating!=='NSFW':(e.contentRating??'Unknown')===contentFilter))&&(!q||normalize([e.title,e.author,e.matchedTitle,...e.alternativeTitles].join(' ')).includes(q))&&({All:true,Matched:e.matchConfirmed,High:e.confidence.startsWith('High'),Uncertain:!!e.mediaId&&!e.matchConfirmed,Unmatched:!e.mediaId,Duplicates:e.possibleDuplicate,Invalid:validate(e,settings).length>0,Excluded:!e.included})[filter]);}
export async function dryRun(api,entries,settings,{signal,progress=()=>{}}={}){const copy=prepareImportEntries(entries,settings);const account=await api.account(signal),plan={destination:settings.destination,account,settings:structuredClone(settings),entries:[],skipped:[],createdAt:new Date().toISOString()};progress('Reading your account library…');const snapshot=api.list?await api.list(signal):null,remote=snapshot?new Map(snapshot.entries.map(e=>[e.mediaId,e])):null;for(const e of copy){signal?.throwIfAborted();const errors=validate(e,settings);if(!e.included||errors.length){plan.skipped.push({key:e.key,title:e.title,mediaId:e.mediaId,result:'Skipped',detail:e._combinedInto?'Combined with '+e._combinedInto+' (same destination ID; maximum progress retained)':e.included?errors.join('; '):'Excluded'});continue;}progress(`Checking ${plan.entries.length+1} / ${copy.length}`);const before=structuredClone(remote?.has(e.mediaId)?remote.get(e.mediaId):snapshot?.complete&&['High · automatic match','High · linked platform ID'].includes(e.confidence)?null:await api.get(e.mediaId,signal));if(before&&settings.existingPolicy==='preserve'){plan.entries.push({key:e.key,title:e.title,before,after:structuredClone(before),action:'Unchanged'});continue;}const after={mediaId:e.mediaId,listId:before?.listId??null,status:e.status,score:convertScore(e.score,e.scoreScale,settings.destination),chapters:settings.preserveChapters?e.chapters:0,volumes:settings.preserveVolumes?e.volumes:0,startDate:e.startDate||before?.startDate||'',finishDate:e.finishDate||before?.finishDate||''};plan.entries.push({key:e.key,title:e.title,before,after,action:before?same(before,after,settings.destination)?'Unchanged':'Update':'Create'});}return plan;}
export function same(a,b,d){return !!a&&!!b&&['mediaId','status','score','chapters','volumes',...(d==='AniList'?['startDate','finishDate']:[])].every(k=>(a[k]??'')===(b[k]??''));}
export async function execute(api,plan,{signal,progress=()=>{},result=()=>{}}={}){if(await api.account(signal)!==plan.account)throw Error('The account changed. Run a new dry run.');const results=[...plan.skipped];for(const e of plan.entries){const row={key:e.key,title:e.title,mediaId:e.after.mediaId,result:'Unchanged',detail:'No change'};if(signal?.aborted){row.result='Cancelled';row.detail='Not attempted';}else if(e.action!=='Unchanged'){try{progress(`Importing ${results.length+1} / ${plan.entries.length+plan.skipped.length}`);const current=await api.get(e.after.mediaId,signal);if(same(current,e.after,plan.destination))row.detail='Already matches; no duplicate write';else if((current!==null||e.before!==null)&&!same(current,e.before,plan.destination)){row.result='Failed';row.detail='Account entry changed since dry run. Prepare a new plan.';}else{await api.save({...e.after,listId:current?.listId??null},signal);row.result='Succeeded';row.detail=e.action;}}catch(error){row.result=signal?.aborted?'Cancelled':'Failed';row.detail='The request may have reached the service. Prepare a fresh dry run before retrying.';}}results.push(row);result(row);}return results;}



export function prepareImportEntries(entries,settings){const copy=structuredClone(entries);if(settings.autoMatch){const groups=new Map();for(const e of copy.filter(e=>e.included&&e.matchConfirmed)){if(!groups.has(e.mediaId))groups.set(e.mediaId,[]);groups.get(e.mediaId).push(e);}for(const found of groups.values()){if(found.length<2)continue;const known=found.filter(e=>e.originalStatus!=='Unknown'),first=known[0]??found[0],group=[first,...found.filter(e=>e!==first)];if((known.length?known:group).every(e=>e.status===first.status)&&group.every(e=>e.score===first.score&&e.scoreScale===first.scoreScale)){merge(group);for(const e of group.slice(1))e._combinedInto=first.title;}}}markDuplicates(copy);return copy;}
